import math
def delay(attempt,base,cap,fraction):
    if type(attempt) is not int or attempt<0 or any(type(v) not in (int,float) or not math.isfinite(v) for v in [base,cap,fraction]) or base<0 or cap<0 or not 0<=fraction<=1:raise ValueError('backoff')
    if base==0 or cap==0:return 0.0
    if base>=cap or attempt>=max(0,math.ceil(math.log2(cap)-math.log2(base))):return cap*fraction
    return math.ldexp(base,attempt)*fraction

