import copy
from urllib.parse import urlsplit,urlunsplit,parse_qsl,urlencode
SENSITIVE={'token','access_token','refresh_token','password','passwd','secret','api_key','key','authorization'}
def sensitive(name):
    name=str(name).casefold().replace('-','_')
    return name in SENSITIVE or any(name.endswith('_'+suffix) for suffix in SENSITIVE)
def clean_url(url):
    parts=urlsplit(url)
    host=parts.hostname or ''
    if ':' in host:host='['+host+']'
    if parts.port is not None:host+=':'+str(parts.port)
    query=urlencode([(k,'[REDACTED]' if sensitive(k) else v) for k,v in parse_qsl(parts.query,keep_blank_values=True)])
    return urlunsplit((parts.scheme,host,parts.path,query,''))
def sanitize(har):
    result=copy.deepcopy(har)
    for entry in result.get('log',{}).get('entries',[]):
        for side in ('request','response'):
            part=entry.get(side,{})
            for header in part.get('headers',[]):
                if header.get('name','').casefold() in {'authorization','proxy-authorization','cookie','set-cookie','x-api-key'}:header['value']='[REDACTED]'
                if header.get('name','').casefold()=='location':header['value']=clean_url(header['value'])
            if 'cookies' in part:part['cookies']=[]
        request=entry.get('request',{})
        if 'url' in request:request['url']=clean_url(request['url'])
        for item in request.get('queryString',[]):
            if sensitive(item.get('name','')):item['value']='[REDACTED]'
        request.pop('postData',None)
        content=entry.get('response',{}).get('content',{})
        for name in ('text','encoding'):content.pop(name,None)
    return result
```

实现 sanitize(har)，深拷贝HAR；脱敏request/response敏感认证头及cookies；request URL去掉userinfo和fragment，敏感查询参数值替换为[REDACTED]，queryString同样处理；删除request.postData与response.content正文，只保留mimeType/size等元数据。保留正常路径、非敏感参数、状态与timings，不修改原对象。敏感键包括token/access_token/refresh_token/password/passwd/secret/api_key/key/authorization及其大小写形式。未知业务字段仍需人工复核，不能宣称自动工具保证所有秘密都被识别。

