import zipfile,stat
from pathlib import Path,PurePosixPath
def extract_limited(zip_path,target,max_files,max_bytes):
    target=Path(target)
    if target.exists():raise ValueError('new target required')
    if any(type(x) is not int or x<0 for x in [max_files,max_bytes]):raise ValueError('budget')
    try:
        with zipfile.ZipFile(zip_path) as z:
            files=[];seen=set();total=0
            for item in z.infolist():
                p=PurePosixPath(item.filename)
                if not p.parts or p.is_absolute() or '..' in p.parts or '\\' in item.filename or ':' in item.filename or str(p) in seen or stat.S_ISLNK(item.external_attr>>16):raise ValueError('unsafe member')
                seen.add(str(p))
                if not item.is_dir():files.append(item);total+=item.file_size
            if len(files)>max_files or total>max_bytes:raise ValueError('expansion budget')
            names=[item.filename for item in files]
            if any(other.startswith(name.rstrip('/')+'/') for name in names for other in seen if other!=name):raise ValueError('file used as directory')
            # Validate CRC and supported compression before creating the target.
            contents=[(item.filename,z.read(item)) for item in files]
            if sum(len(data) for _,data in contents)>max_bytes:raise ValueError('actual expansion budget')
    except (zipfile.BadZipFile,RuntimeError,NotImplementedError) as e:raise ValueError('invalid archive') from e
    target.mkdir(parents=True)
    for name,data in contents:
        p=target/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
    return [name for name,_ in contents]
