import urllib.request,urllib.error,time
def get_retry(url,max_attempts):
    if type(max_attempts) is not int or not 1<=max_attempts<=5:raise ValueError('attempts')
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
    for attempt in range(max_attempts):
        try:
            with opener.open(url,timeout=2) as response:return response.read()
        except urllib.error.HTTPError as e:
            if e.code not in (429,503) or attempt+1==max_attempts:raise
            text=e.headers.get('Retry-After','0')
            if not text.isascii() or not text.isdigit() or not 0<=int(text)<=2:raise
            time.sleep(int(text))
```

