            db.execute('CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,payload TEXT NOT NULL,allocation TEXT NOT NULL,rolled_back INTEGER NOT NULL DEFAULT 0)')
    def apply(self,batch_id,total,weights):
