                return json.loads(old[1])
            db.execute('INSERT INTO batches(id,payload,allocation) VALUES(?,?,?)',(batch_id,payload,json.dumps(result,sort_keys=True)))
            return result
    def rollback(self,batch_id):
        with closing(sqlite3.connect(self.path)) as db,db:
            db.execute('BEGIN IMMEDIATE')
            row=db.execute('SELECT allocation FROM batches WHERE id=?',(batch_id,)).fetchone()
            if row is None:raise KeyError(batch_id)
            db.execute('UPDATE batches SET rolled_back=1 WHERE id=?',(batch_id,))
            return {key:-value for key,value in json.loads(row[0]).items()}
    def balances(self):
        with closing(sqlite3.connect(self.path)) as db:
            rows=db.execute('SELECT allocation,rolled_back FROM batches').fetchall()
