import socket,math
def probe(host,port,timeout):
    if host!='127.0.0.1' or type(timeout) not in (int,float) or not math.isfinite(timeout) or timeout<=0:raise ValueError('probe')
    try:sock=socket.create_connection((host,port),timeout=timeout)
    except ConnectionRefusedError:return ('connect','refused')
    except TimeoutError:return ('connect','timeout')
    with sock:
        try:value=sock.recv(1)
        except TimeoutError:return ('read','timeout')
        return ('read','data' if value else 'eof')
